import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Calculate due date based on terms
  const dueDateResult = calculateDueDate(issueDate, terms);
  if (!dueDateResult.ok) return dueDateResult;
  const dueDate = dueDateResult.value;

  // Validate lines
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Get tier discount for lines without their own discount
  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent (if provided, must be valid)
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }
    // Use line's discount if provided, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    // Validate SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const discount = roundCents(total * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a single line (on the amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const taxableAmount = total - discount;
  const vatRate = line.vatRate ?? 0;
  const vat = roundCents(taxableAmount * vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
    vat += lineVAT(line);
  }
  subtotal = roundCents(subtotal);
  discount = roundCents(discount);
  vat = roundCents(vat);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent (if provided, must be valid)
  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }
  const discount = discountPercent ?? 0;

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Find existing line
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    // Line exists, increase qty
    newLines = invoice.lines.map((line, index) =>
      index === existingLineIndex ? { ...line, qty: line.qty + qty } : line,
    );
  } else {
    // New line
    const product = productResult.value;
    newLines = [
      ...invoice.lines,
      {
        sku,
        name: product.name,
        qty,
        unitPrice: product.unitPrice,
        vatRate: product.vatRate,
        discountPercent: discount,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if it's the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, number?: string }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return ok(addDays(issueDate, 14));
  } else if (terms === 'NET30') {
    return ok(addDays(issueDate, 30));
  } else if (terms === 'EOM') {
    // End of month: last day of the month of the issue date
    const [year, month] = issueDate.split('-').map(Number);
    // Use UTC to find last day of month
    const lastDayUtc = new Date(Date.UTC(year, month, 0)); // month + 1, day 0 = last day of previous month
    const lastDay = lastDayUtc.getUTCDate();
    const monthStr = String(month).padStart(2, '0');
    const dayStr = String(lastDay).padStart(2, '0');
    return ok(`${year}-${monthStr}-${dayStr}`);
  } else {
    return fail('TERMS_INVALID');
  }
}

function isValidDiscountPercent(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

