  assert.equal(totals.vat, 14475); // €144.75 = €99.75 + €45 + €0
  // subtotal €1500 - discount €75 + vat €144.75 = €1569.75
  assert.equal(totals.total, 156975);
});

test('invoiceTotals vat is sum of line VATs, not percentage of total', () => {
  // Create invoice where if VAT were calculated on invoice total, result would be different
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 50, vatRate: 21 }, // €1000, 50% disc = €500, €500 taxable, 21% VAT = €105
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // €1000, 0% VAT = €0
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: €1000 + €1000 = €2000
  // If VAT were 21% of (€2000 - €500): (2000 - 500) * 0.21 = €315
  // But it should be only €105 (21% VAT only on first line's €500 taxable amount)
  assert.equal(totals.subtotal, 200000); // €2000
  assert.equal(totals.discount, 50000); // €500
  assert.equal(totals.vat, 10500); // €105
  assert.equal(totals.total, 160500); // €2000 - €500 + €105 = €1605
});

test('invoiceTotals with 0% VAT lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 6000, discountPercent: 0, vatRate: 0 }, // Workshop day (VAT exempt)
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

test('invoiceTotals vat calculation respects discount', () => {
  // Same product, one with discount, one without
  const withDiscount = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 50, vatRate: 21 }, // €100, 50% disc = €50, 21% VAT = €10.50
    ],
  };
  const withoutDiscount = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }, // €100, 0% disc, 21% VAT = €21
    ],
  };
  const totalsWithDiscount = invoiceTotals(withDiscount);
  const totalsWithoutDiscount = invoiceTotals(withoutDiscount);

  assert.equal(totalsWithDiscount.vat, 1050); // €10.50
  assert.equal(totalsWithoutDiscount.vat, 2100); // €21
  assert.equal(totalsWithoutDiscount.vat, totalsWithDiscount.vat * 2);
});

