  // Issue on the 1st
  let r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.value.dueDate, '2026-10-31');

  // Issue on the 15th
  r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.value.dueDate, '2026-10-31');

  // Issue on the 31st
  r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-31',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('applyVoucher adds voucher to draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);

  const result = applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SAVE10');
  assert.equal(result.value.voucher.amount, 10000);
});

test('applyVoucher rejects non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = applyVoucher(issued.value, { code: 'SAVE10', amount: 10000 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects if voucher already exists', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);

  const first = applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });
  assert.equal(first.ok, true);

  const second = applyVoucher(first.value, { code: 'SAVE20', amount: 20000 });
  assert.deepEqual(second, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher validates amount is positive integer', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(applyVoucher(r.value, { code: 'CODE', amount: 0 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });
  assert.deepEqual(applyVoucher(r.value, { code: 'CODE', amount: -1000 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });
  assert.deepEqual(applyVoucher(r.value, { code: 'CODE', amount: 10.5 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });
});

test('applyVoucher does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const original = JSON.parse(JSON.stringify(r.value));

  applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });

  assert.deepEqual(r.value, original);
  assert.equal(r.value.voucher, undefined);
});

test('invoiceTotals includes voucher', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }], // €850 + 21% VAT
  });
  const withVoucher = applyVoucher(r.value, { code: 'SAVE10', amount: 50000 });

  const totals = invoiceTotals(withVoucher.value);
  assert.equal(totals.voucher, 50000);
  // total = subtotal - discount + vat - voucher
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

test('invoiceTotals voucher is zero when not applied', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
  });

  const totals = invoiceTotals(r.value);
  assert.equal(totals.voucher, 0);
});

test('voucher reduces total correctly', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }], // €50 + 21% VAT
  });
  const totals1 = invoiceTotals(r.value);

  const withVoucher = applyVoucher(r.value, { code: 'SAVE5', amount: 5000 });
  const totals2 = invoiceTotals(withVoucher.value);

  assert.equal(totals2.total, totals1.total - 5000);
});

test('voucher total is clamped at zero', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1, discountPercent: 0 }], // €0.50 + VAT
  });
  const totals1 = invoiceTotals(r.value);

  // Apply voucher larger than total
  const withVoucher = applyVoucher(r.value, { code: 'BIG', amount: totals1.total + 10000 });
  const totals2 = invoiceTotals(withVoucher.value);

  assert.equal(totals2.total, 0);
});

test('voucher preserves other invoice properties', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const withVoucher = applyVoucher(r.value, { code: 'VOUCHER', amount: 10000 });
  assert.equal(withVoucher.ok, true);
  assert.equal(withVoucher.value.customerId, 'C-001');
  assert.equal(withVoucher.value.issueDate, '2026-10-07');
  assert.equal(withVoucher.value.status, 'draft');
  assert.equal(withVoucher.value.lines.length, r.value.lines.length);
});

