test('invoiceTotals vat is sum of line VATs, not percentage of total', () => {
  // Create invoice where if VAT were calculated on invoice total, result would be different
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 50, vatRate: 21 }, // €1000, 50% disc = €500, €500 taxable, 21% VAT = €105
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // €1000, 0% VAT = €0
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: €1000 + €1000 = €2000
  // If VAT were 21% of (€2000 - €500): (2000 - 500) * 0.21 = €315
  // But it should be only €105 (21% VAT only on first line's €500 taxable amount)
  assert.equal(totals.subtotal, 200000); // €2000
  assert.equal(totals.discount, 50000); // €500
  assert.equal(totals.vat, 10500); // €105
  assert.equal(totals.total, 160500); // €2000 - €500 + €105 = €1605
});

